values
  ('86c7a380-710a-404a-b1fd-8f9745285e16', 'رول دارچین با شکلات چیپسی 🍫🤎', 'fantasy', 'رول لطیف و خوش‌عطر با عطر گرم دارچین و تکه‌های شکلات چیپسی؛ ترکیبی جذاب از طعم دارچین و شکلات در هر لقمه.', 'assets/images/product-2e43e3e1a8.jpg', '', 100000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '1 minutes'),
  ('39abed87-0cef-4184-9343-e1af190971a5', 'نان خمیرترش 🍞', 'fantasy', 'نان دست‌ساز با خمیرترش طبیعی، بافتی خوش‌جو و پوسته‌ای ترد؛ خوش‌عطر، سالم و مناسب برای یک صبحانه یا وعده لذیذ.', 'assets/images/product-eb5ed4abfe.jpg', '', 180000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '2 minutes'),
  ('4ddd0c1c-0a7e-4a60-8ded-1e3012996e94', 'بربری فانتزی 🥖✨', 'fantasy', 'نان نرم و لطیف با بافتی سبک و خوش‌خوراک؛ انتخابی مناسب برای تهیه انواع برگر و ساندویچ‌های خوشمزه.', 'assets/images/product-979f9f369a.jpg', '', 40000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '3 minutes'),
  ('c96469b7-6305-4f66-947d-c1c9211b9bd5', 'نان مک‌دونالد 🍔', 'fantasy', 'نان نرم و لطیف با بافتی سبک و خوش‌خوراک؛ انتخابی مناسب برای تهیه انواع برگر و ساندویچ‌های خوشمزه.', 'assets/images/product-6f3fcbfee0.jpg', '', 35000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '4 minutes'),
  ('16a1b072-2764-46fa-9bfb-e6210ab89fdd', 'نان فوکاچیا با زیتون 🫒🍞', 'fantasy', 'فوکاچیای تازه و خوش‌عطر با بافتی نرم و رویه‌ای طلایی، همراه با زیتون‌های خوش‌طعم؛ انتخابی عالی برای یک میان‌وعده یا کنار غذا.', 'assets/images/product-3e41295e5b.jpg', '', 350000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '5 minutes'),
  ('7d1324c4-a77b-437e-9cad-d00a1ecfebc2', 'نان سیر مخصوص سالاد سزار 🧄🥖', 'fantasy', 'نان ترد و خوش‌عطر با طعم دلنشین سیر؛ انتخابی عالی برای سرو در کنار سالاد سزار و تکمیل طعم یک وعده لذیذ.', 'assets/images/product-05aec6f267.jpg', '', 500000, null, 'کیلو', timestamptz '2026-01-01 00:00:00+00' + interval '6 minutes'),
  ('018f1978-917b-477d-ab96-f71d1e5c9c8f', 'تست بریوش 🍞✨', 'fantasy', 'نان بریوش لطیف و خوش‌عطر با بافتی نرم و کمی شیرین؛ مناسب برای صبحانه، تست کردن و تهیه انواع ساندویچ.', 'assets/images/product-54ec64effb.jpg', '', 320000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '7 minutes'),
  ('17916fdb-1ca7-484d-b825-05b574f9648b', 'کیک اورئو 🍰', 'cake', 'کیک لطیف و خوش‌عطر با کرم خامه‌ای و تکه‌های بیسکویت اورئو؛ انتخابی جذاب برای عاشقان طعم شکلات و اورئو.', 'assets/images/product-907d227113.jpg', '', 250000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '8 minutes'),
  ('a64e4544-1865-4c2c-983a-5fbc288420aa', 'کروسان نوتلا 🥐🍫', 'cake', 'کروسان تازه و ترد با مغز نوتلای خوش‌طعم؛ ترکیبی دلپذیر از خمیر لطیف و شکلات فندقی که هر لقمه‌اش لذت‌بخشه.', 'assets/images/product-d471d8d3e9.jpg', '', 220000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '9 minutes'),
  ('9fe59d33-be68-4308-ad52-64809a066029', 'رول نیویورکی 🥐🍫', 'cake', 'رول تهیه‌شده از خمیر کروسان با بافتی ترد و لایه‌لایه، پرشده با نوتلای خوش‌طعم؛ ترکیبی جذاب و وسوسه‌انگیز برای عاشقان شکلات.', 'assets/images/product-aede57fb84.jpg', '', 220000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '10 minutes'),
  ('908d8c41-5b83-4cc4-b327-6fc60011211c', 'چیزکیک سن‌سباستین 🍰✨', 'cake', 'چیزکیکی لطیف و خامه‌ای با رویه‌ی کاراملی و برشته؛ بافتی نرم و طعمی غنی برای عاشقان دسرهای خاص.', 'assets/images/product-66ffb5f836.jpg', '', 230000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '11 minutes'),
  ('a110ae83-e22d-4715-bbef-392daac13241', 'کیک هویج و گردو 🥕🌰', 'cake', 'کیکی نرم و خوش‌عطر با ترکیب هویج و گردوی تازه؛ بافتی لطیف و طعمی دلچسب و خانگی.', 'assets/images/product-44836be63a.jpg', '', 180000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '12 minutes'),
  ('54c49634-10ea-4a1e-9540-809b7ad14b26', 'شیرینی نارگیلی 🥥✨', 'cake', 'شیرینی لطیف و خوش‌عطر با طعم دلنشین نارگیل؛ بافتی نرم و لذیذ با عطر و طعمی دوست‌داشتنی.', 'assets/images/product-59a118c3a6.jpg', '', 1400000, null, 'کیلو', timestamptz '2026-01-01 00:00:00+00' + interval '13 minutes'),
  ('26c9805f-7ac8-4cde-b063-77e1be1651b3', 'شیرینی چایی قزوین 🍪✨', 'cake', 'شیرینی سنتی و خوش‌عطر قزوینی با بافتی لطیف و طعمی دلنشین؛ انتخابی عالی برای همراهی با چای و پذیرایی.', 'assets/images/product-95692ba451.jpg', '', 1000000, null, 'کیلو', timestamptz '2026-01-01 00:00:00+00' + interval '14 minutes'),
  ('989647b2-9311-4b79-9dac-cf730c44901c', 'چاکلت تویست 🍫🥐', 'cake', 'خمیر ترد و لایه‌لایه، پرشده با کرم فیلینگ و شکلات چیپسی؛ ترکیبی جذاب از بافت ترد، کرم لطیف و طعم دلنشین شکلات.', 'assets/images/product-b87fef6a3f.jpg', '', 130000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '15 minutes'),
  ('6617f479-7035-4a8a-9e4e-e0b9c653aeec', 'بی‌بی‌کیک شکلاتی 🍫🍰', 'cake', 'کیک شکلاتی نرم و پوک با بافتی لطیف و سبک، همراه با کرم شکلاتی خوش‌طعم و طعمی متعادل و دلنشین؛ یک انتخاب کلاسیک و محبوب برای عاشقان شکلات.', 'assets/images/product-660aa497ea.jpg', '', 200000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '16 minutes'),
  ('bdb89edd-dfaa-4d66-8a49-96d9ec2afe44', 'کیک خیس شکلاتی 🍫🍰', 'cake', 'کیکی نرم و مرطوب با طعم غنی شکلات و بافتی لطیف؛ انتخابی وسوسه‌انگیز برای عاشقان شکلات و دسرهای خوشمزه', 'assets/images/product-14b4cee7e5.jpg', '', 200000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '17 minutes'),
  ('78da0e9b-2d5b-468e-9c72-0318f90539ae', 'دنیش میوه فصل 🍓🥐', 'dessert', 'خمیر لطیف و ترد کروسان، پرشده با کرم فیلینگ و میوه‌های تازه فصل؛ ترکیبی جذاب و خوش‌طعم برای یک شیرینی خاص و دلچسب.', 'assets/images/product-37c3dd92dc.jpg', '', 180000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '18 minutes'),
  ('54749608-f6da-4341-8761-e8b2b9286967', 'کرامبل سیب و دارچین 🍎✨', 'dessert', 'ترکیبی دلنشین از سیب‌های خوش‌عطر و دارچین، با رویه‌ای ترد و کرامبلی؛ گرم، خوش‌عطر و دلچسب برای عاشقان طعم‌های کلاسیک.', 'assets/images/product-9e75d80a5d.jpg', '', 160000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '19 minutes'),
  ('6e69dd6e-f447-4099-910c-a13e86592980', 'دسر لوتوس 🍮🤎', 'dessert', 'دسری لطیف و خامه‌ای با کرم و بیسکویت لوتوس؛ ترکیبی جذاب از بافت خامه‌ای و طعم کاراملی و دلنشین بیسکویت لوتوس.', 'assets/images/product-734ec86767.jpg', '', 200000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '20 minutes'),
  ('48ddbe7c-ffd3-43fc-8d69-d51a4716287e', 'کوکی پسته با استویا 🍪💚', 'cookie', 'کوکی خوش‌عطر و خوش‌طعم با پسته و شیرینی ملایم استویا؛ انتخابی لذیذ برای دوستداران طعم پسته و گزینه‌های کم‌شیرین‌تر', 'assets/images/product-10989b6c71.jpg', '', 1400000, null, '', timestamptz '2026-01-01 00:00:00+00' + interval '21 minutes'),
  ('3095a031-6340-4bfc-87dd-85a87280a02c', 'قطاب سه‌مغز 🌰✨', 'cookie', 'قطاب خوش‌عطر و ترد با مغز ترکیبی از سه نوع مغز، با طعمی اصیل و دلچسب؛ مناسب برای عاشقان شیرینی‌های سنتی ایرانی.', 'assets/images/product-02ade566b1.jpg', '', 1400000, null, 'کیلو', timestamptz '2026-01-01 00:00:00+00' + interval '22 minutes'),
  ('efda35cc-4284-49f6-81c5-4f981d9aef3c', 'کوکی دبل چاکلت 🍪🍫', 'cookie', 'کوکی شکلاتی با بافتی نرم و لذیذ و پر از تکه‌های شکلات؛ انتخابی فوق‌العاده برای عاشقان طعم غنی و عمیق شکلات.', 'assets/images/product-23a420d02c.jpg', '', 1200000, null, 'کیلو', timestamptz '2026-01-01 00:00:00+00' + interval '23 minutes')
